/// <summary>
/// Method for posting a sales trade agreement
/// </summary>
/// <param name = "_request"></param>
/// <returns></returns>
public ARGSalesAgreeJourPostResponse postSalesTradeAgreement(ARGSalesAgreeJourPostRequest _request)
{
    var response = new ARGSalesAgreeJourPostResponse();

    changecompany(_request.parmDataAreaId())
    {
        response = this.postSalesAgreement(_request.parmSalesAgreeJourPostClass());
        return response;
    }
}

public ARGSalesAgreeJourPostResponse postSalesAgreement(ARGSalesAgreeJourPostClass _salesAgreeJourPostClass)
{
    PriceDiscAdmCheckPost   priceDiscAdmCheckPost = new PriceDiscAdmCheckPost(false);//To make sure posting is happen
    ARGSalesAgreeJourPostResponse response = new ARGSalesAgreeJourPostResponse();
    ARGCustomBatchJobLog    customBatchJobLog;
    str errorMsg;

    try
    {
        priceDiscAdmCheckPost.initJournalNum(_salesAgreeJourPostClass.parmJournalNum());
        priceDiscAdmCheckPost.run();

        response.parmSuccess(true);
        response.parmDebugMessage(strFmt("Trade agreement: %1 successfully posted",_salesAgreeJourPostClass.parmJournalNum()));
    }
    catch (Exception::UpdateConflict)
    {
        throw Exception::UpdateConflict;
    }
    catch (Exception::CLRError)
    {
        throw Exception::CLRError;
    }
    catch
    {
        errorMsg = this.getErrorStr();
        response.parmSuccess(false);
        response.parmErrorMessage(errorMsg);

        customBatchJobLog.clear();
        customBatchJobLog.LogMessage = errorMsg;
        customBatchJobLog.JournalId = _salesAgreeJourPostClass.parmJournalNum();
        customBatchJobLog.insert();
    }
    return response;
}

/// <summary>
/// Method to capture the standard error and send it the perticular catch of the method.
/// </summary>
/// <returns>error</returns>
public str getErrorStr()
{
    SysInfologEnumerator    enumerator;
    SysInfologMessageStruct msgStruct;
    Exception               exception;
    str                     error;

    enumerator = SysInfologEnumerator::newData(infolog.cut());

    while (enumerator.moveNext())
    {
        msgStruct = new SysInfologMessageStruct(enumerator.currentMessage());
        exception = enumerator.currentException();
        error = strfmt("@SYS82282"+ ' '+"@MCR26302", error, msgStruct.message());
    }

    return error;
}
